/* ---- 40_ex.js ---- */
/* ---------- exercises of the vocabulary lane (docs/LANGUAGES.md §6.2) ---------- */
const clusters = s => { try { return [...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(s)].map(x => x.segment); } catch (e) { return [...s]; } };

