  const score = x => { const k = UI.C.concepts[(x.senses || [])[0]] || {}; return (k.subgroup && k.subgroup === con.subgroup ? 0 : k.field && k.field === con.field ? 1 : 2) + (x.pos === me.pos ? 0 : 3) + Math.random(); };
