const SPK_SKIP = 'button, .lx-opts, .lx-opt, select, option, label, .lx-tile, .lx-tile1, .lx-slot, .lx-tiles, .lx-kbd, .lx-cands, .lx-tutor, [data-nospeak], .lx-hidecol, .lx-input, header, .lx-tmsg, .lx-diff, .lx-roman';
